- {"self_ref":"\#/texts/24","parent":{"$ref":"\#/texts/0"},"children":[],"content_layer":"body","label":"paragraph","prov":[],"orig":"(c) using the measurement obtained as an indicator of the toxicity of the analyte.","text":"(c) using the measurement obtained as an indicator of the toxicity of the analyte."}
- {"self_ref":"\#/texts/25","parent":{"$ref":"\#/texts/0"},"children":[],"content_layer":"body","label":"paragraph","prov":[],"orig":"In a still further aspect, the invention provides a kit for performing the above-stated assay comprising an assay reagent with signal generating metabolic activity and means for contacting the assay reagent with a sample to be assayed for an analyte.","text":"In a still further aspect, the invention provides a kit for performing the above-stated assay comprising an assay reagent with signal generating metabolic activity and means for contacting the assay reagent with a sample to be assayed for an analyte."}
